"""Create a single-file HTML deck, including an actual Vercel screenshot."""
from pathlib import Path
import base64
import html
import json

URL='https://neuranx-fund-intelligence.vercel.app/'

def main():
    shot=base64.b64encode(Path('output/screenshots/vercel-live-dark.jpg').read_bytes()).decode()
    status_path=Path('deployment/status.json')
    status=json.loads(status_path.read_text()) if status_path.exists() else {'oci':'OCI provisioning is pending. The live interview demo runs on Vercel; persistent uploads are not connected.'}
    slides=[
    ('A note to the team',f'''<p class="intro">Dear NeuraNx team,</p><h1>Financial document<br>intelligence, with evidence</h1><p class="lead">I approached this assignment as an FDE engagement: understand the analyst’s decision, inspect the real report, ship a usable workflow, and make uncertainty visible.</p><div class="byline">Atharva Swami · FDE interview demonstration · 7 November 2026</div><p class="fine">ABC Company Fund and every financial figure in the source report are fictional. This project is an independent proposed solution, not NeuraNx’s internal architecture.</p>'''),
    ('Problem statement','''<h1>A fluent answer can still<br>be the wrong answer</h1><p class="lead">An analyst needs to interrogate a 50-page fund report spanning historical performance, quarterly tables, portfolio allocations, and forecasts.</p><div class="columns"><div><h2>Evidence is fragmented</h2><p>Numbers, footnotes, charts, and assumptions live on different pages. A summary alone hides their provenance.</p></div><div><h2>The source conflicts with itself</h2><p>Repeated quarterly tables disagree. Forecasts and actuals need separate labels. Currency glyphs are unresolved.</p></div><div><h2>Accuracy must be inspectable</h2><p>Numeric answers need deterministic calculations, exact page references, and explicit disclosure of missing or conflicting evidence.</p></div></div>'''),
    ('Proposed solution','''<h1>A research workspace that<br>keeps the source close</h1><div class="sequence"><div><b>01</b><h2>Inspect</h2><p>Preserve page text, tables, raw values, and cell coordinates.</p></div><div><b>02</b><h2>Validate</h2><p>Report inconsistencies independently, without overwriting values.</p></div><div><b>03</b><h2>Answer</h2><p>Route exact questions to typed facts and narrative questions to retrieved passages.</p></div><div><b>04</b><h2>Verify</h2><p>Open the original page beside the answer and inspect the calculation.</p></div></div><p class="lead">Light and dark themes support the same workflow. The custom web UI runs without Streamlit.</p>'''),
    ('Live product',f'''<div class="product-head"><h1>The deployed workspace</h1><a href="{URL}" target="_blank" rel="noopener">{URL}</a></div><img class="product" src="data:image/jpeg;base64,{shot}" alt="Actual screenshot of the hosted Fund Intelligence workspace on Vercel"><p class="fine">Captured from the live Vercel deployment. Public demo uses the verified sample report; new document ingestion requires the persistent backend.</p>'''),
    ('A verified numeric answer','''<p class="kicker">Question · How did the fund perform against the benchmark in 2025?</p><h1>15.6% − 13.4% = <span>2.20 pp</span></h1><div class="columns two"><div><h2>Source-reported</h2><p>Fund return: 15.6%<br>Benchmark return: 13.4%<br>Annual Performance Review, page 9</p></div><div><h2>Calculated</h2><p>Difference = fund return − benchmark return<br>Computed using Python Decimal<br>The answer links back to the original source page</p></div></div><p class="callout">The language model is not the authority for arithmetic. The public Vercel question path was checked against this exact example.</p>'''),
    ('Conflicts remain visible','''<h1>One year.<br>Five reported NAV values.</h1><div class="values"><div><strong>192.9</strong><p>Annual · p. 9</p></div><div><strong>194.7</strong><p>Quarterly · p. 16</p></div><div><strong>192.5</strong><p>Quarterly · p. 19</p></div><div><strong>194.0</strong><p>Quarterly · p. 22</p></div><div><strong>195.5</strong><p>Quarterly · p. 25</p></div></div><p class="lead">These are the 2025 annual NAV and four Q4 closing observations. The report does not establish which version is authoritative.</p><p class="callout">Keep every observation with its page. Do not average, silently select a version, or “repair” the source.</p>'''),
    ('Architecture','''<h1>Separate evidence, facts,<br>calculations, and explanation</h1><div class="architecture"><div><h2>Vercel web UI</h2><p>Overview · Questions · Source pages · Quality findings</p></div><div class="flow-arrow">↓ HTTPS</div><div class="arch-row"><div><h2>Query router</h2><p>Structured · Narrative · Reconciliation</p></div><div><h2>Evidence + calculations</h2><p>Typed observations · Decimal arithmetic · Source references</p></div><div><h2>Answer layer</h2><p>Evidence response · Optional constrained LLM composer</p></div></div><div class="flow-arrow">↓ source provenance</div><div><h2>Verified report evidence</h2><p>Raw page text · Table cells · Historical / forecast labels · Issue register</p></div></div><p class="fine">Live: Vercel CDN → Python API proxy → Cloudflare HTTPS demo tunnel → FastAPI on OCI. Evidence is retained on the VM. Target extension: authenticated ingestion, durable jobs, and optional PostgreSQL/pgvector.</p>'''),
    ('Validation and engineering judgment','''<h1>Check the brief<br>against the actual artifact</h1><div class="columns"><div><h2>50 pages · 346 observations</h2><p>49 extracted tables. Every observation retains its raw token and provenance. The report generates eight warnings and five informational notes.</p></div><div><h2>36 tests · 12 scenarios</h2><p>Local checks cover extraction, arithmetic, citations, ambiguity, uploads, document isolation, source rendering, review state, and provider fallback.</p></div><div><h2>Two useful corrections</h2><p>The sample quarterly inputs compound to 16.74%. The chart’s highest tick, 360, is not its axis maximum; the 390.3 forecast fits within the plotted range.</p></div></div><p class="fine">Default retrieval is BM25 keyword search. Provider embeddings, LLM composition, and PostgreSQL/pgvector are optional paths; live provider calls have not been exercised.</p>'''),
    ('Deployment and next steps',f'''<h1>A live demo.<br>An explicit deployment boundary.</h1><div class="columns two"><div><h2>Vercel · Live</h2><p>Custom light/dark UI, sample report exploration, source citations, deterministic questions, and downloadable evidence.</p><a class="live-url" href="{URL}" target="_blank" rel="noopener">{URL}</a></div><div><h2>OCI · Live demo server</h2><p>{html.escape(status['oci'])}</p><p>PDF uploads use private browser workspaces, with original files and extracted evidence stored on OCI. Hosted limits: 4 MB, 200 pages, and 10 reports per workspace. Findings export as a formatted, printable HTML report.</p></div></div><p class="fine">Customer deployment requires authentication, per-document authorization, durable jobs, retention controls, monitoring, and a labeled evaluation set. Always Free eligibility depends on the tenancy’s home region, remaining allowance, and available host capacity.</p>'''),
    ('Try the workflow',f'''<h1>Ask. Inspect. Challenge.</h1><ol class="demo"><li>Compare the fund with the benchmark in 2025; open page 9.</li><li>Ask which year had the highest return; inspect the 2021 NAV warning.</li><li>Compare annual and quarterly 2025 NAV; inspect all four quarterly versions.</li></ol><a class="closing-url" href="{URL}" target="_blank" rel="noopener">{URL}</a><p class="lead">The next customer conversation is about which source they trust, what decisions follow, and how discrepancies should be reviewed.</p><p class="fine">Source: supplied ABC Company Fund PDF; local extraction and evaluation results. UI guidance: Unslop by Damir Sokolovsky, CC BY 4.0. Deployment references: <a href="https://vercel.com/docs/functions/runtimes/python">Vercel Python runtime</a> · <a href="https://docs.oracle.com/en-us/iaas/Content/FreeTier/freetier_topic-Always_Free_Resources.htm">OCI Always Free resources</a></p>''')]
    content=''.join(f'<section class="slide" id="slide-{i+1}" aria-label="Slide {i+1}: {title}"><header><span>NeuraNx · FDE solution</span><span>{title}</span></header><article>{body}</article><footer><span>Financial document intelligence</span><span>{i+1:02d} / {len(slides):02d}</span></footer></section>' for i,(title,body) in enumerate(slides))
    css='''*{box-sizing:border-box}html{scroll-snap-type:y proximity;scroll-behavior:smooth}body{margin:0;background:#111512;color:#e7ede7;font:20px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif}.slide{position:relative;height:100vh;min-height:720px;max-width:1600px;margin:auto;padding:24px 56px 24px;display:flex;flex-direction:column;scroll-snap-align:start;border-bottom:1px solid #303b32}header,footer{display:flex;justify-content:space-between;gap:24px;font-size:13px;color:#a1afa3}header{padding-bottom:28px;border-bottom:1px solid #303b32}footer{padding-top:20px;border-top:1px solid #303b32;margin-top:auto}article{padding:24px 0;min-height:0;flex:1;display:flex;flex-direction:column;justify-content:center}h1{font:400 clamp(38px,4vw,60px)/1.12 Georgia,serif;letter-spacing:-1.5px;margin:0 0 20px}h1 span{color:#94cba4}h2{font-size:23px;font-weight:500;margin:0 0 12px}p{margin:0 0 20px;color:#b6c1b7}.intro,.kicker{font-size:17px;color:#94cba4}.lead{font-size:21px;max-width:1050px;line-height:1.6}.byline{font-size:17px;margin:20px 0 28px}.fine{font-size:13px;color:#96a699;line-height:1.65;margin-top:20px;max-width:1120px}a{color:#94cba4;text-decoration:underline;text-underline-offset:4px}.columns{display:grid;grid-template-columns:repeat(3,1fr);gap:36px;margin:20px 0}.columns.two{grid-template-columns:1fr 1fr}.columns p{font-size:17px}.columns>div{border-top:2px solid #52715a;padding-top:20px}.sequence{display:grid;grid-template-columns:repeat(4,1fr);gap:32px;margin:32px 0}.sequence b{font:36px Georgia,serif;color:#94cba4;display:block;margin-bottom:24px}.sequence p{font-size:18px}.product-head{display:flex;justify-content:space-between;align-items:center;gap:28px}.product-head h1{font-size:42px;margin:0 0 20px}.product-head a{font-size:15px}.product{display:block;width:100%;max-height:50vh;object-fit:contain;object-position:top left;border:1px solid #303b32;border-radius:8px;background:#151916}.values{display:flex;justify-content:space-between;gap:24px;padding:28px 0;margin:0 0 32px;border-top:1px solid #303b32;border-bottom:1px solid #303b32}.values strong{font-size:42px;font-weight:400;color:#94cba4;font-variant-numeric:tabular-nums}.values p{font-size:15px;margin:8px 0}.callout{padding:20px 0;border-top:1px solid #52715a;color:#d5e8d8;font-size:21px}.architecture>div:not(.flow-arrow){padding:16px 20px;background:#1a241c;border:1px solid #38473a}.architecture h2{font-size:20px;margin:0 0 4px}.architecture p{font-size:15px;margin:0}.architecture .arch-row{display:grid;grid-template-columns:repeat(3,1fr);gap:28px}.flow-arrow{padding:8px 20px;color:#94cba4;font-size:14px}.live-url{font-size:17px;overflow-wrap:anywhere}.closing-url{font:28px/1.5 ui-monospace,monospace;margin:24px 0 40px;overflow-wrap:anywhere}.demo{padding-left:28px;max-width:1080px}.demo li{padding-left:12px;margin:12px 0;font-size:24px}.controls{position:fixed;left:50%;transform:translateX(-50%);bottom:12px;display:flex;gap:8px;z-index:20}.controls button{border:1px solid #607763;background:#19221b;color:#e7ede7;font:14px inherit;padding:8px 16px;border-radius:6px;cursor:pointer}.controls button:focus-visible,a:focus-visible{outline:2px solid #94cba4;outline-offset:4px}@media(max-width:800px){.slide{padding:24px;min-height:100svh;height:auto}header,footer{font-size:11px}.columns,.columns.two,.sequence{grid-template-columns:1fr;gap:20px}.lead{font-size:20px}.columns p{font-size:17px}.values{flex-wrap:wrap;gap:20px}.values strong{font-size:32px}.product-head{display:block}.product-head a{display:block;margin-bottom:16px;font-size:12px}.architecture .arch-row{grid-template-columns:1fr}.demo li{font-size:19px}.closing-url{font-size:19px}.product{max-height:none}.controls{opacity:.85}}@media print{@page{size:landscape;margin:0}body{background:#fff;color:#17231a;font-size:16px}.slide{min-height:100vh;break-after:page;page-break-after:always;border:0;padding:26px 44px}h1{font-size:42px;color:#17231a}.lead{font-size:20px}p,header,footer,.fine{color:#45574a}a,h1 span,.values strong,.sequence b{color:#226644}.columns p{font-size:16px}.columns{gap:28px}.product{max-height:63vh}.product-head h1{font-size:32px}.architecture>div:not(.flow-arrow){background:#f0f4ee}.controls{display:none}.fine{font-size:11px}.demo li{font-size:20px}.closing-url{font-size:23px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}'''
    script='''let current=0;const slides=[...document.querySelectorAll('.slide')];function go(delta){current=Math.max(0,Math.min(slides.length-1,current+delta));slides[current].scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});history.replaceState(null,'','#slide-'+(current+1))}document.getElementById('prev').onclick=()=>go(-1);document.getElementById('next').onclick=()=>go(1);document.addEventListener('keydown',e=>{if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();go(1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();go(-1)}if(e.key==='Home'){current=0;go(0)}if(e.key==='End'){current=slides.length-1;go(0)}});const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)current=slides.indexOf(e.target)}),{threshold:.5});slides.forEach(s=>observer.observe(s));'''
    output=Path('output/Fund_Intelligence_FDE_Deck.html');output.write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fund Intelligence · FDE interview · Atharva Swami</title><style>{css}</style></head><body>{content}<nav class="controls" aria-label="Presentation controls"><button id="prev" aria-label="Previous slide">←</button><button id="next" aria-label="Next slide">→</button><button onclick="window.print()">Print / Save PDF</button></nav><script>{script}</script></body></html>')
    print(str(output.resolve()))

if __name__=='__main__':main()
